body.script:
(function () {
  var canvas = document.getElementById('spCanvas');
  var scaleEl = document.getElementById('spScale');
  var statusEl = document.getElementById('spStatus');
  var resEl = document.getElementById('spRes');
  var zoomEl = document.getElementById('spZoom');
  var teamName = (document.getElementById('spBoot') || {}).getAttribute('data-team') || 'squad';
  var busy = false;
  var shell = document.getElementById('spShell');
  var PALETTE_KEY = 'ac_squad_poster_palette';

  function setPalette(id) {
    if (!shell || !id) return;
    shell.setAttribute('data-palette', id);
    try { localStorage.setItem(PALETTE_KEY, id); } catch (e) {}
    var swatches = document.querySelectorAll('.sp-swatch');
    for (var i = 0; i < swatches.length; i++) {
      swatches[i].classList.toggle('is-active', swatches[i].getAttribute('data-palette') === id);
    }
    setStatus('Palette: ' + id.replace(/-/g, ' '), 'is-ok');
  }
  (function initPalette() {
    var saved = '';
    try { saved = localStorage.getItem(PALETTE_KEY) || ''; } catch (e) {}
    if (saved) setPalette(saved);
    else setPalette('pace-lime');
    var row = document.getElementById('spPaletteRow');
    if (row) {
      row.addEventListener('click', function (ev) {
        var btn = ev.target.closest ? ev.target.closest('.sp-swatch') : null;
        if (!btn) return;
        setPalette(btn.getAttribute('data-palette'));
      });
    }
  })();

  function setStatus(msg, cls) {
    if (!statusEl) return;
    statusEl.textContent = msg || '';
    statusEl.className = 'sp-status' + (cls ? ' ' + cls : '');
  }

  function applyZoom() {
    if (!scaleEl || !zoomEl) return;
    var v = zoomEl.value;
    if (v === 'fit') {
      var avail = Math.max(320, window.innerWidth - 48);
      var z = Math.min(1, avail / 1080);
      scaleEl.style.transform = 'scale(' + z.toFixed(3) + ')';
      scaleEl.style.marginBottom = ((1920 * z) - 1920) + 'px';
    } else {
      var n = parseFloat(v) || 1;
      scaleEl.style.transform = 'scale(' + n + ')';
      scaleEl.style.marginBottom = ((1920 * n) - 1920) + 'px';
    }
  }
  if (zoomEl) zoomEl.addEventListener('change', applyZoom);
  window.addEventListener('resize', applyZoom);
  applyZoom();

  function waitImages() {
    var imgs = Array.prototype.slice.call(canvas.querySelectorAll('img'));
    return Promise.all(imgs.map(function (img) {
      return new Promise(function (res) {
        if (img.complete && img.naturalWidth) { res(); return; }
        img.onload = img.onerror = function () { res(); };
      });
    }));
  }

  function slugify(s) {
    return String(s || 'squad').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'squad';
  }

  function renderPoster() {
    var scale = parseInt(resEl && resEl.value, 10) || 2;
    // Lock live square pixel sizes so html2canvas export does not stretch
    var liveFrames = canvas.querySelectorAll('.sp-card-frame');
    for (var lf = 0; lf < liveFrames.length; lf++) {
      var rect = liveFrames[lf].getBoundingClientRect();
      var side = Math.max(1, Math.round(Math.min(rect.width, rect.height)));
      liveFrames[lf].setAttribute('data-export-side', String(side));
    }
    return waitImages().then(function () {
      return html2canvas(canvas, {
        scale: scale,
        useCORS: true,
        allowTaint: true,
        backgroundColor: null,
        logging: false,
        imageTimeout: 0,
        width: 1080,
        height: 1920,
        windowWidth: 1080,
        windowHeight: 1920,
        onclone: function (doc) {
          var frames = doc.querySelectorAll('.sp-card-frame');
          for (var f = 0; f < frames.length; f++) {
            var side = parseInt(frames[f].getAttribute('data-export-side') || '0', 10);
            frames[f].style.position = 'relative';
            frames[f].style.overflow = 'hidden';
            frames[f].style.display = 'flex';
            frames[f].style.alignItems = 'center';
            frames[f].style.justifyContent = 'center';
            frames[f].style.flex = 'none';
            frames[f].style.aspectRatio = '1 / 1';
            if (side > 0) {
              frames[f].style.width = side + 'px';
              frames[f].style.height = side + 'px';
              frames[f].style.maxWidth = side + 'px';
              frames[f].style.maxHeight = side + 'px';
            }
          }
          var imgs = doc.querySelectorAll('.sp-card-photo');
          for (var i = 0; i < imgs.length; i++) {
            var img = imgs[i];
            img.style.position = 'relative';
            img.style.inset = 'auto';
            img.style.width = 'auto';
            img.style.height = 'auto';
            img.style.maxWidth = '100%';
            img.style.maxHeight = '100%';
            img.style.objectFit = 'contain';
            img.style.objectPosition = 'center center';
          }
        }
      });
    });
  }

  function blobFromCanvas(c, fmt) {
    return new Promise(function (resolve, reject) {
      if (fmt === 'png') {
        c.toBlob(function (b) { b ? resolve(b) : reject(new Error('PNG failed')); }, 'image/png');
      } else {
        c.toBlob(function (b) { b ? resolve(b) : reject(new Error('JPG failed')); }, 'image/jpeg', 0.97);
      }
    });
  }

  function downloadBlob(blob, filename) {
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(function () { URL.revokeObjectURL(url); }, 2500);
  }

  function withBusy(fn) {
    if (busy) return;
    busy = true;
    ['spDlPng', 'spDlJpg', 'spCopy', 'spShare'].forEach(function (id) {
      var el = document.getElementById(id);
      if (el) el.disabled = true;
    });
    Promise.resolve()
      .then(fn)
      .catch(function (err) {
        console.error(err);
        setStatus('Error: ' + (err && err.message ? err.message : err), 'is-err');
      })
      .then(function () {
        busy = false;
        ['spDlPng', 'spDlJpg', 'spCopy', 'spShare'].forEach(function (id) {
          var el = document.getElementById(id);
          if (el) el.disabled = false;
        });
      });
  }

  function exportFmt(fmt) {
    withBusy(function () {
      var scale = parseInt(resEl && resEl.value, 10) || 2;
      var wh = (1080 * scale) + '×' + (1920 * scale);
      setStatus('Rendering ' + wh + ' ' + fmt.toUpperCase() + '…');
      return renderPoster().then(function (c) {
        return blobFromCanvas(c, fmt).then(function (blob) {
          var ext = fmt === 'png' ? 'png' : 'jpg';
          downloadBlob(blob, 'squad-poster-' + slugify(teamName) + '-' + (1080 * scale) + 'x' + (1920 * scale) + '.' + ext);
          setStatus('Downloaded ' + wh + ' · ready for Instagram Stories', 'is-ok');
        });
      });
    });
  }

  var pngBtn = document.getElementById('spDlPng');
  var jpgBtn = document.getElementById('spDlJpg');
  if (pngBtn) pngBtn.addEventListener('click', function () { exportFmt('png'); });
  if (jpgBtn) jpgBtn.addEventListener('click', function () { exportFmt('jpg'); });

  var printBtn = document.getElementById('spPrint');
  if (printBtn) printBtn.addEventListener('click', function () { window.print(); });

  var copyBtn = document.getElementById('spCopy');
  if (copyBtn) copyBtn.addEventListener('click', function () {
    withBusy(function () {
      setStatus('Copying image…');
      return renderPoster().then(function (c) {
        return blobFromCanvas(c, 'png').then(function (blob) {
          if (navigator.clipboard && window.ClipboardItem) {
            return navigator.clipboard.write([new ClipboardItem({'image/png': blob})]).then(function () {
              setStatus('Image copied to clipboard', 'is-ok');
            });
          }
          throw new Error('Clipboard image not supported in this browser');
        });
      });
    });
  });

  var shareBtn = document.getElementById('spShare');
  if (shareBtn) shareBtn.addEventListener('click', function () {
    withBusy(function () {
      setStatus('Preparing share…');
      return renderPoster().then(function (c) {
        return blobFromCanvas(c, 'png').then(function (blob) {
          var file = new File([blob], 'squad-poster-' + slugify(teamName) + '.png', {type: 'image/png'});
          if (navigator.share && navigator.canShare && navigator.canShare({files: [file]})) {
            return navigator.share({
              files: [file],
              title: teamName + ' Squad',
              text: teamName + ' — Official Squad Roster'
            }).then(function () {
              setStatus('Shared', 'is-ok');
            });
          }
          downloadBlob(blob, file.name);
          setStatus('Share unavailable — PNG downloaded instead', 'is-ok');
        });
      });
    });
  });
})();
